import {SYMBOLS,symbolSVG,symbolMarkup,symbolBounds} from './notation.js';
import {RhythmDocument,lanes,placePoint,RHYTHM_WIDTH as W,RHYTHM_HEIGHT as H} from './rhythm-model.js';
import {downloadCanvas} from './ink.js';
const KEY='band-board:rhythm:v1';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class RhythmWriter {
 constructor(root,{notify=()=>{},exit=()=>{},fullscreen=()=>{}}={}){
  this.root=root;this.notify=notify;this.selected=null;this.drag=null;this.visible=false;
  let saved={};try{saved=JSON.parse(localStorage.getItem(KEY))||{}}catch{}
  this.doc=new RhythmDocument(saved);
  root.innerHTML=`<div class="rhythm-toolbar"><button data-r-action="exit">← Band board</button><div class="rhythm-title"><span class="eyebrow">MAKE A RHYTHM</span><h1>Rhythm Writer</h1></div><div class="rhythm-edit-actions"><button data-r-action="undo" title="Undo (Ctrl+Z)">↶ <span>Undo</span></button><button data-r-action="redo" title="Redo (Ctrl+Shift+Z)">↷ <span>Redo</span></button><button data-r-action="copy">Copy</button><button data-r-action="delete">Delete</button><button data-r-action="clear">Clear</button><button data-r-action="save">Save image</button><button data-r-action="fullscreen" aria-label="Full screen">⛶</button></div></div><div class="rhythm-workspace"><aside class="rhythm-palette"><div class="palette-title">DRAG A COPY<span>Tap to add, too.</span></div><div class="rhythm-cloners">${SYMBOLS.map(s=>`<button class="rhythm-cloner" data-clone="${s.id}" aria-label="${s.label}. Drag a copy, or tap to add." draggable="false">${symbolSVG(s.id,17)}<span>${s.label}</span></button>`).join('')}</div></aside><div class="rhythm-paper-column"><div class="rhythm-options"><span class="free-placement-label">Free placement</span><label class="rhythm-guide-rows">Guide rows <select data-r-setting="rows"><option value="1">1</option><option value="2">2</option><option value="3">3</option></select></label><label>Size <select data-r-setting="size"><option value="24">Small</option><option value="32">Medium</option><option value="40">Large</option></select></label><label><input data-r-setting="guides" type="checkbox">Guide lines</label><span class="rhythm-save-state">Saved on this device</span></div><div class="rhythm-stage"><svg id="rhythm-canvas" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="group" aria-label="Rhythm writing board" tabindex="0"></svg></div><div class="rhythm-hint"><span>Drag notes and rests anywhere. They stay where you put them.</span><span id="rhythm-count"></span></div></div></div>`;
  this.svg=root.querySelector('#rhythm-canvas');this.ghost=document.createElement('div');this.ghost.className='rhythm-drag-ghost';this.ghost.hidden=true;document.body.append(this.ghost);
  root.addEventListener('pointerdown',e=>this.down(e));document.addEventListener('pointermove',e=>this.move(e),{passive:false});document.addEventListener('pointerup',e=>this.up(e));document.addEventListener('pointercancel',e=>this.cancel(e));
  root.addEventListener('click',e=>{const b=e.target.closest('[data-r-action]');if(b){switch(b.dataset.rAction){case'exit':exit();break;case'fullscreen':fullscreen();break;case'undo':this.doc.undo();this.changed();break;case'redo':this.doc.redo();this.changed();break;case'copy':this.duplicate();break;case'delete':this.remove();break;case'clear':this.doc.clear();this.selected=null;this.changed();this.notify('Rhythm cleared. Undo brings it back.');break;case'save':this.saveImage();break}}const cl=e.target.closest('[data-clone]');if(cl&&e.detail===0)this.append(cl.dataset.clone)});
  root.addEventListener('change',e=>{const key=e.target.dataset.rSetting;if(!key)return;const value=e.target.type==='checkbox'?e.target.checked:Number(e.target.value);this.doc.configure(key,value);this.changed()});
  document.addEventListener('keydown',e=>this.key(e));window.addEventListener('blur',()=>this.cancel());this.render();
 }
 setVisible(value){this.visible=value;if(!value)this.cancel();else this.render()}
 point(e){const matrix=this.svg.getScreenCTM();if(!matrix)return null;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());return {x:p.x,y:p.y}}
 inside(p){return p&&p.x>=0&&p.y>=0&&p.x<=W&&p.y<=H}
 down(e){if(e.button!==0||!e.isPrimary||this.drag)return;const clone=e.target.closest('[data-clone]'),group=e.target.closest('[data-r-id]');if(!clone&&!group){if(e.target.closest('#rhythm-canvas')){this.selected=null;this.render()}return}e.preventDefault();const item=group?this.doc.items.find(i=>i.id===group.dataset.rId):null,type=clone?clone.dataset.clone:item.type,p=this.point(e);
  this.drag={pointer:e.pointerId,type,id:item?.id||null,startX:e.clientX,startY:e.clientY,moved:false,offset:item?{x:p.x-item.x,y:p.y-item.y}:{x:0,y:0},position:null};if(item)this.selected=item.id;this.root.setPointerCapture(e.pointerId);this.ghost.innerHTML=symbolSVG(type,19);this.move(e);this.render();
 }
 move(e){const d=this.drag;if(!d||e.pointerId!==d.pointer)return;e.preventDefault();if(Math.hypot(e.clientX-d.startX,e.clientY-d.startY)>5)d.moved=true;const p=this.point(e);d.position=this.inside(p)?placePoint(d.type,{x:p.x-d.offset.x,y:p.y-d.offset.y},this.doc):null;this.ghost.hidden=!!d.position;this.ghost.style.left=(e.clientX-64)+'px';this.ghost.style.top=(e.clientY-83)+'px';this.renderPaper()}
 up(e){const d=this.drag;if(!d||e.pointerId!==d.pointer)return;this.move(e);const p=this.point(e);this.drag=null;this.ghost.hidden=true;
  if(d.position&&this.inside(p)){if(d.id)this.doc.move(d.id,d.position);else this.selected=this.doc.add(d.type,d.position)?.id}
  else if(!d.id&&!d.moved){this.append(d.type);return}
  this.changed();
 }
 cancel(e){if(e&&this.drag&&e.pointerId!==this.drag.pointer)return;this.drag=null;this.ghost.hidden=true;if(this.svg)this.render()}
 append(type){this.selected=this.doc.add(type,this.doc.nextPosition(type))?.id;this.changed()}
 duplicate(){const i=this.doc.items.find(i=>i.id===this.selected);if(!i)return;this.selected=this.doc.add(i.type,this.doc.nextPosition(i.type,{x:i.x+35,y:i.y+35}))?.id;this.changed()}
 remove(){if(this.selected)this.doc.remove(this.selected);this.selected=null;this.changed()}
 changed(){if(this.selected&&!this.doc.items.some(i=>i.id===this.selected))this.selected=null;try{localStorage.setItem(KEY,JSON.stringify(this.doc.snapshot()));this.root.querySelector('.rhythm-save-state').textContent='Saved on this device'}catch{this.root.querySelector('.rhythm-save-state').textContent='Use Save image to keep this rhythm';this.notify('Browser storage is full. Save an image to keep your rhythm.')}this.render()}
 itemMarkup(item,{exporting=false,preview=false}={}){const space=this.doc.size,b=symbolBounds(item.type,space),width=Math.max(44,b.right-b.left+24),height=Math.max(44,b.bottom-b.top+24),left=(b.left+b.right-width)/2,top=(b.top+b.bottom-height)/2,selected=!exporting&&(preview||item.id===this.selected);
  const faded=!exporting&&!preview&&this.drag?.id===item.id;
  let inner=symbolMarkup(item.type,0,0,space);
  if(!exporting){inner=`<rect class="rhythm-hit" x="${left}" y="${top}" width="${width}" height="${height}" fill="transparent"/>`+inner;if(selected)inner+=`<rect x="${left}" y="${top}" width="${width}" height="${height}" rx="8" fill="none" stroke="${preview?'#b37b1d':'#17695f'}" stroke-width="2" ${preview?'stroke-dasharray="7 5"':''} pointer-events="none"/>`}
  const label=SYMBOLS.find(s=>s.id===item.type)?.label||'';
  return `<g transform="translate(${item.x} ${item.y})" color="#111820" opacity="${faded?'.25':'1'}" ${exporting||preview?'':`data-r-id="${escape(item.id)}" role="button" tabindex="0" aria-label="${label}. Move with arrow keys or drag."`}>${inner}</g>`;
 }
 paperMarkup(exporting=false){let body=`<rect width="${W}" height="${H}" fill="white"/>`;
  if(this.doc.guides)for(const y of lanes(this.doc.rows))body+=`<path d="M36 ${y}H1164" stroke="#d8ddd8" stroke-width="1.4"/>`;
  if(!this.doc.items.length&&!this.drag?.position&&!exporting)body+=`<text x="600" y="335" text-anchor="middle" font-family="Segoe UI,Arial,sans-serif" font-size="25" fill="#7b898c">Your rhythm starts here.</text><text x="600" y="375" text-anchor="middle" font-family="Segoe UI,Arial,sans-serif" font-size="17" fill="#7b898c">Drag a symbol from the shelf, or tap one to add it.</text>`;
  for(const i of this.doc.items){if(!exporting&&this.drag?.id===i.id&&this.drag.position)continue;body+=this.itemMarkup(i,{exporting});}if(!exporting&&this.drag?.position)body+=this.itemMarkup({id:'preview',type:this.drag.type,...this.drag.position},{preview:true});return body;
 }
 renderPaper(){this.svg.innerHTML=this.paperMarkup()}
 render(){this.renderPaper();this.root.querySelector('.rhythm-guide-rows').classList.toggle('hidden',!this.doc.guides);for(const key of ['rows','size','guides']){const el=this.root.querySelector(`[data-r-setting="${key}"]`);if(el.type==='checkbox')el.checked=this.doc[key];else el.value=this.doc[key]}this.root.querySelector('[data-r-action="undo"]').disabled=!this.doc.undoStack.length;this.root.querySelector('[data-r-action="redo"]').disabled=!this.doc.redoStack.length;for(const a of ['copy','delete'])this.root.querySelector(`[data-r-action="${a}"]`).disabled=!this.selected;this.root.querySelector('#rhythm-count').textContent=this.doc.items.length?`${this.doc.items.length} ${this.doc.items.length===1?'symbol':'symbols'}`:''}
 key(e){if(!this.visible||globalThis.document?.querySelector('dialog[open]')||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?this.doc.redo():this.doc.undo();this.changed();return}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();this.doc.redo();this.changed();return}if(e.key==='Escape'){this.cancel();this.selected=null;this.render();return}if(e.key==='Delete'||e.key==='Backspace'){if(this.selected){e.preventDefault();this.remove()}return}if(e.key==='Enter'&&e.target.dataset.rId){this.selected=e.target.dataset.rId;this.render();this.svg.focus();return}
  if(this.selected&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const i=this.doc.items.find(i=>i.id===this.selected);if(!i)return;let p={x:i.x,y:i.y};const amount=e.shiftKey?20:5;if(e.key==='ArrowLeft')p.x-=amount;if(e.key==='ArrowRight')p.x+=amount;if(e.key==='ArrowUp'||e.key==='ArrowDown'){p.y+=e.key==='ArrowUp'?-amount:amount}this.doc.move(i.id,p);this.changed();this.svg.focus()}
 }
 async saveImage(){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${this.paperMarkup(true)}</svg>`,url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');canvas.width=W*2;canvas.height=H*2;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);downloadCanvas(canvas,'Band-Board-Rhythm.png')}catch{this.notify('The image could not be saved. Please try again.')}finally{URL.revokeObjectURL(url)}}
}
